<?php declare(strict_types=1);
$page=max(1,(int)($_GET['page']??1));try{$accesses=$application->adminAccesses()->list($page,20);}catch(\Throwable){$accesses=[];}$adminContent=static function()use($accesses):void{?><section class="admin-panel"><?php if($accesses===[]):admin_empty('Nenhum acesso administrativo','Os acessos de suporte aparecerão aqui.');else:?><div class="table-responsive"><table class="table os-table"><thead><tr><th>Empresa</th><th>Usuário</th><th>IP</th><th>Início</th><th>Encerramento</th><th>Status</th></tr></thead><tbody><?php foreach($accesses as $access):?><tr><td><?=admin_h($access['nome_fantasia']??'Empresa #'.$access['empresa_id'])?></td><td><?=admin_h($access['usuario']??'Usuário #'.$access['usuario_id'])?></td><td><?=admin_h($access['ip']??'—')?></td><td><?=admin_h($access['iniciado_em']??'—')?></td><td><?=admin_h($access['encerrado_em']??'—')?></td><td><?=($access['encerrado_em']??null)?'Encerrado':'Em andamento'?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php };
